static std::string utf8(const std::wstring&s){if(s.empty())return {};int n=WideCharToMultiByte(CP_UTF8,0,s.data(),(int)s.size(),0,0,0,0);std::string r(n,0);WideCharToMultiByte(CP_UTF8,0,s.data(),(int)s.size(),r.data(),n,0,0);return r;}
static std::wstring wide(const std::string&s){if(s.empty())return {};int n=MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),0,0);std::wstring r(n,0);MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),r.data(),n);return r;}
static fs::path path(const std::string&s){return fs::path(wide(s));}
static std::string str(const fs::path&p){return utf8(p.wstring());}
static std::string assetLabel(std::string value){if(value.size()>8&&value.substr(value.size()-8)==".virtual"){value=value.substr(7,value.size()-15);std::replace(value.begin(),value.end(),'_',' ');}return value;}
