static std::string folder(const std::string&initial){IFileOpenDialog*d=nullptr;std::string r;if(SUCCEEDED(CoCreateInstance(CLSID_FileOpenDialog,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&d)))){DWORD flags;d->GetOptions(&flags);d->SetOptions(flags|FOS_PICKFOLDERS|FOS_FORCEFILESYSTEM);IShellItem*i=nullptr;if(SUCCEEDED(SHCreateItemFromParsingName(wide(initial).c_str(),nullptr,IID_PPV_ARGS(&i)))){d->SetFolder(i);i->Release();}if(SUCCEEDED(d->Show(windowHandle))&&SUCCEEDED(d->GetResult(&i))){PWSTR p=nullptr;if(SUCCEEDED(i->GetDisplayName(SIGDN_FILESYSPATH,&p))){r=utf8(p);CoTaskMemFree(p);}i->Release();}d->Release();}return r;}
static bool textInput(const char*label,std::string&s){std::vector<char>b(std::max(size_t(4096),s.size()+1024));memcpy(b.data(),s.data(),s.size());if(ImGui::InputText(label,b.data(),b.size())){s=b.data();return true;}return false;}
static glm::vec3 vec3(const J&j,int o=0){return {j[o].get<float>(),j[o+1].get<float>(),j[o+2].get<float>()};}
static glm::quat quaternion(const J&j,int o=3){return glm::normalize(glm::quat(j[o+3].get<float>(),j[o].get<float>(),j[o+1].get<float>(),j[o+2].get<float>()));}
struct Pose{glm::vec3 p{0},s{1};glm::quat q{1,0,0,0};};
static Pose pose(const J&j){return {vec3(j),vec3(j,7),quaternion(j)};}
static glm::mat4 matrix(const Pose&p){return glm::translate(glm::mat4(1),p.p)*glm::mat4_cast(p.q)*glm::scale(glm::mat4(1),p.s);}
struct Bone{std::string name;int parent;Pose bind;glm::mat4 inverse;};
struct Vertex{glm::vec3 p,n;glm::vec2 uv;std::vector<int>ids;std::vector<float>weights;};
struct Mesh{std::string name;std::vector<Vertex>vertices;std::vector<unsigned>indices;GLuint texture=0;bool selected=true;};
struct Model{std::string name;std::vector<Bone>bones;std::vector<Mesh>meshes;std::map<std::string,int>index;std::vector<glm::mat4>world;};
struct Track{int bone,flags;std::vector<Pose>samples;};
struct Clip{std::string name,source,socket;float duration;std::vector<Track>weapon,arms;bool selected=true;};
static GLuint getTexture(const fs::path&p){std::ifstream f(p,std::ios::binary);if(!f)return 0;unsigned w,h;f.read((char*)&w,4);f.read((char*)&h,4);if(!w||!h||w>16384||h>16384)return 0;std::vector<unsigned char>pixels(size_t(w)*h*4);if(!f.read((char*)pixels.data(),pixels.size()))return 0;for(unsigned y=0;y<h/2;y++)for(unsigned x=0;x<w*4;x++)std::swap(pixels[size_t(y)*w*4+x],pixels[size_t(h-1-y)*w*4+x]);GLuint t;glGenTextures(1,&t);glBindTexture(GL_TEXTURE_2D,t);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,pixels.data());return t;}
static void dispose(Model&m){for(auto&x:m.meshes)if(x.texture)glDeleteTextures(1,&x.texture);m={};}
static Model model(const J&j,const fs::path&cache){Model m;if(j.is_null())return m;m.name=j.at("name");for(auto&b:j.at("bones")){Bone bone;bone.name=b.at("name");bone.parent=b.at("parent");bone.bind=pose(b.at("local"));auto v=b.at("inverse").get<std::vector<float>>();bone.inverse=glm::make_mat4(v.data());m.index[bone.name]=(int)m.bones.size();m.bones.push_back(bone);}m.world.resize(m.bones.size());for(auto&d:j.at("meshes")){Mesh mesh;mesh.name=d.at("name");auto&mat=j.at("materials").at(d.at("material").get<std::string>());if(mat.contains("albedo"))mesh.texture=getTexture(cache/path(mat.at("albedo").get<std::string>()+".rgba"));for(size_t i=0;i<d.at("positions").size();i++){Vertex v;v.p=vec3(d["positions"][i]);v.n=vec3(d["normals"][i]);v.uv={d["uvs"][i][0].get<float>(),d["uvs"][i][1].get<float>()};v.ids=d["boneIndices"][i].get<std::vector<int>>();v.weights=d["weights"][i].get<std::vector<float>>();mesh.vertices.push_back(v);}mesh.indices=d["indices"].get<std::vector<unsigned>>();m.meshes.push_back(std::move(mesh));}return m;}
static std::vector<Track> tracks(const J&c,const Model&m){std::vector<Track>ts;if(c.is_null())return ts;for(auto&t:c.at("tracks")){auto it=m.index.find(t.at("name"));if(it==m.index.end())continue;Track track{it->second,t.at("flags"),{}};for(auto&s:t.at("samples"))track.samples.push_back(pose(s));ts.push_back(std::move(track));}return ts;}
static void animate(Model&m,const std::vector<Track>&tracks,float time){std::vector<Pose>poses;for(auto&b:m.bones)poses.push_back(b.bind);for(auto&t:tracks){if(t.samples.empty())continue;float sample=std::clamp(time*30,0.f,float(t.samples.size()-1));int i=(int)sample,j=std::min(i+1,(int)t.samples.size()-1);float f=sample-i;auto&a=t.samples[i];auto&b=t.samples[j];auto&p=poses[t.bone];if(t.flags&1)p.p=glm::mix(a.p,b.p,f);if(t.flags&2)p.q=glm::slerp(a.q,b.q,f);if(t.flags&4)p.s=glm::mix(a.s,b.s,f);}for(size_t i=0;i<m.bones.size();i++){auto local=matrix(poses[i]);m.world[i]=m.bones[i].parent<0?local:m.world[m.bones[i].parent]*local;}}
static void drawModel(const Model&m,const glm::mat4&attachment,bool wire){glPushMatrix();glMultMatrixf(glm::value_ptr(attachment));std::vector<glm::mat4>skin;for(size_t i=0;i<m.bones.size();i++)skin.push_back(m.world[i]*m.bones[i].inverse);for(auto&mesh:m.meshes){if(!mesh.selected)continue;if(mesh.texture&&!wire){glEnable(GL_TEXTURE_2D);glBindTexture(GL_TEXTURE_2D,mesh.texture);glColor3f(1,1,1);}else{glDisable(GL_TEXTURE_2D);glColor3f(.67f,.74f,.78f);}std::vector<glm::vec3>p(mesh.vertices.size()),n(mesh.vertices.size());for(size_t i=0;i<mesh.vertices.size();i++){auto&v=mesh.vertices[i];glm::vec4 vp(0);glm::vec3 vn(0);for(size_t k=0;k<v.ids.size();k++){if(v.weights[k]==0)continue;vp+=(skin[v.ids[k]]*glm::vec4(v.p,1))*v.weights[k];vn+=(glm::mat3(skin[v.ids[k]])*v.n)*v.weights[k];}p[i]=glm::vec3(vp);n[i]=glm::normalize(vn);}glBegin(GL_TRIANGLES);for(unsigned ix:mesh.indices){glNormal3fv(glm::value_ptr(n[ix]));glTexCoord2fv(glm::value_ptr(mesh.vertices[ix].uv));glVertex3fv(glm::value_ptr(p[ix]));}glEnd();}glPopMatrix();}
static void screenshot(const fs::path&p,int w,int h){std::vector<unsigned char>pixels(size_t(w)*h*4);glReadPixels(0,0,w,h,GL_BGRA_EXT,GL_UNSIGNED_BYTE,pixels.data());BITMAPFILEHEADER file{};BITMAPINFOHEADER info{};file.bfType=0x4d42;file.bfOffBits=sizeof(file)+sizeof(info);file.bfSize=file.bfOffBits+(DWORD)pixels.size();info.biSize=sizeof(info);info.biWidth=w;info.biHeight=h;info.biPlanes=1;info.biBitCount=32;info.biCompression=BI_RGB;std::ofstream out(p,std::ios::binary);out.write((char*)&file,sizeof(file));out.write((char*)&info,sizeof(info));out.write((char*)pixels.data(),pixels.size());}
static void screenshotPreview(const fs::path&p,GLuint texture){int w=0,h=0;glBindTexture(GL_TEXTURE_2D,texture);glGetTexLevelParameteriv(GL_TEXTURE_2D,0,GL_TEXTURE_WIDTH,&w);glGetTexLevelParameteriv(GL_TEXTURE_2D,0,GL_TEXTURE_HEIGHT,&h);std::vector<unsigned char>pixels(size_t(w)*h*4);glGetTexImage(GL_TEXTURE_2D,0,GL_BGRA_EXT,GL_UNSIGNED_BYTE,pixels.data());BITMAPFILEHEADER file{};BITMAPINFOHEADER info{};file.bfType=0x4d42;file.bfOffBits=sizeof(file)+sizeof(info);file.bfSize=file.bfOffBits+(DWORD)pixels.size();info.biSize=sizeof(info);info.biWidth=w;info.biHeight=h;info.biPlanes=1;info.biBitCount=32;info.biCompression=BI_RGB;std::ofstream out(p,std::ios::binary);out.write((char*)&file,sizeof(file));out.write((char*)&info,sizeof(info));out.write((char*)pixels.data(),pixels.size());}
// An asymmetric fixture verifies decoded top-left image coordinates through OpenGL.
static bool verifyTextureOrientation(const fs::path&p){if(!fs::exists(p))return false;GLuint t=getTexture(p);glViewport(0,0,4,4);glDisable(GL_SCISSOR_TEST);glDisable(GL_LIGHTING);glDisable(GL_DEPTH_TEST);glDisable(GL_BLEND);glEnable(GL_TEXTURE_2D);glBindTexture(GL_TEXTURE_2D,t);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glMatrixMode(GL_PROJECTION);glLoadIdentity();glMatrixMode(GL_MODELVIEW);glLoadIdentity();glColor4f(1,1,1,1);glBegin(GL_QUADS);glTexCoord2f(0,0);glVertex2f(-1,-1);glTexCoord2f(1,0);glVertex2f(1,-1);glTexCoord2f(1,1);glVertex2f(1,1);glTexCoord2f(0,1);glVertex2f(-1,1);glEnd();unsigned char px[64];glReadPixels(0,0,4,4,GL_RGBA,GL_UNSIGNED_BYTE,px);glDeleteTextures(1,&t);return px[2]>240&&px[0]<10&&px[48]>240&&px[49]<10&&px[60]<10&&px[61]>240;}
